import test from "node:test";
import assert from "node:assert/strict";
import { run, lastResult } from "../../src/tax/index.ts";

const cases: Array<[number, number]> = [
  [0, 56353],
  [1, 52871],
  [7, 64006],
  [42, 67532],
];

test("tax service matches the reference results", () => {
  for (const [x, expected] of cases) {
    assert.equal(run(x), expected, `run(${x})`);
    assert.equal(lastResult(x), expected);
  }
});

test("tax service rejects invalid input", () => {
  assert.throws(() => run(-1), RangeError);
});
