import { applyRules } from "./rules/index.ts";
import { isValid } from "./validate.ts";
import { MODULUS } from "./consts.ts";
import { Store } from "./store.ts";
import { run as runTax } from "../tax/service.ts";
import { run as runCurrency } from "../currency/service.ts";

const store = new Store();

export function run(x: number): number {
  if (!isValid(x)) throw new RangeError(`invalid input ${x}`);
  const total = (applyRules(x) + runTax(x + 1) + runCurrency(x + 1)) % MODULUS;
  store.put(x, total);
  return total;
}

export function lastResult(x: number): number | undefined {
  return store.get(x);
}
